function exExecutionActions(exE){if(exE.state==='INTERRUPTED')return card('执行已中断',`<div class="note warn">${I('unplug')}<span>${exE.reason}。不自动重放；请先检查已写入文件、外部请求与工具副作用。</span></div><div class="row wrap" style="margin-top:12px">${exButton('确认副作用后恢复',`exExecutionConfirm('RUNNING')`,'primary',MACHINES.find(exM=>exM.id===exE.machine).st!=='ONLINE','原机器离线；请先恢复连接，或换机器开故障重试分支')}${exButton('换机器开故障重试分支','exRetryMachine()')}${exButton('标记失败',`exExecutionConfirm('FAILED')`,'danger')}</div>`);if(exE.state==='PAUSED')return card('执行已暂停',`<p>${exE.reason}</p>${exButton('恢复',`exExecutionChange('${exCurrentExecution}','RUNNING')`,'primary')}`);if(exE.state==='RUNNING')return card('执行中',`<div class="row wrap">${exButton('停止',`exExecutionConfirm('CANCELLED')`,'danger')}${exButton('暂停',`exExecutionChange('${exCurrentExecution}','PAUSED')`)}</div><p class="muted small">停止会取消本次执行，已发生的副作用不会回滚；确认时需重新认证。</p>`);return card('执行已结束',`<div class="row wrap">${S(exE.state)}<span class="muted small">执行成功不等于团队接受；以验证结果与授权裁决为准。</span>${exButton('合并到主分支','', '',true,'未取得团队 APPROVE 裁决，或当前执行不是可合并的工作执行')}</div>`);}
function exExecutionConfirm(state){const exE=exExecutions[exCurrentExecution];exConfirm(state==='RUNNING'?'恢复中断执行':state==='FAILED'?'标记执行失败':'停止执行',state==='RUNNING'?'恢复可能继续调用外部工具，请确认没有需要先处理的重复写入。':'不会回滚已经产生的文件与外部请求；旧日志与证据仍保留。',`execution|${exCurrentExecution}|${state}`,true,state==='RUNNING');}
