function exRetryMachine(){exModal('换机器 · 故障重试分支',`<div class="note warn">不重放旧执行。你需检查工具副作用；新分支保留父执行的日志与证据。</div><label for="exRetryMachine">目标机器</label><select id="exRetryMachine">${MACHINES.map(exM=>`<option value="${exM.id}" ${exM.st!=='ONLINE'||!exM.rt.some(exR=>exR.startsWith('Claude Code'))?'disabled':''}>${exM.n} · ${exM.st!=='ONLINE'?'离线，不可选':!exM.rt.some(exR=>exR.startsWith('Claude Code'))?'未安装相同运行时': '可用'}</option>`).join('')}</select><label class="row"><input id="exRetryCheck" type="checkbox">我已检查工具副作用</label><p class="muted small">需重新认证；原型仅演示，未启动机器上的执行。</p>`,'exRetrySubmit()','确认创建故障重试分支',true);}
function exRetrySubmit(){if(!document.getElementById('exRetryCheck').checked)return toast('请先检查并确认工具副作用');const exOld=exExecutions[exCurrentExecution],exMachine=document.getElementById('exRetryMachine').value,exId='EX-DEMO-'+Date.now();exExecutions[exId]={...exOld,machine:exMachine,state:'CREATED',branch:'#2 · 故障重试 1',parent:exCurrentExecution,cost:0,time:'刚刚',duration:'0 秒',reason:'已创建演示分支，尚未派发',level:0};closeModal();go('execution/'+exId);}
