  if(index===3)return `<div class="grid g12"><div class="c8">${card('证据来源',exEvidence(exE),{icon:'file-check'})}</div><div class="c4">${card('产物清单',exKV([['变更提交','9f3c2a1 · +42 / −8'],['测试报告','output/test-report.json'],['完成声明',exE.state==='SUCCEEDED'&&exCurrentExecution!=='EX-9080'?'claim.json · 已附证据':'尚无工作完成声明'],['采集状态',exE.state==='SUCCEEDED'?'已完成':'部分采集 · 等待执行结束']]),{icon:'files'})}</div></div>`;
