function exEvidence(exE){return ['COMMIT','TEST_REPORT','LOG'].map((exType,exI)=>`<div class="ev" style="margin-bottom:12px"><div class="row wrap"><b>EV-${301+exI} · ${['修改提交 9f3c2a1','测试报告 · 24 通过 / 0 失败 / 1 跳过','执行日志 · 12 KB · 未截断'][exI]}</b>${S(exE.state==='SUCCEEDED'?'PASSED':'PENDING')}${exButton('查看内容',`exViewEvidence(${exI})`,'sm ghost')}</div><div class="prov">${A(exE.actor)} ${PEOPLE[exE.actor].n} · ${MACHINES.find(exM=>exM.id===exE.machine).n} · ${exE.runtime} · <time title="2026-10-11T07:41:00Z">今天 07:41</time></div><div class="mono xs">${exType} · SHA-256 ${exHash(exCurrentExecution+exType).slice(0,8)} ${exButton('复制全值',`exCopy('${exHash(exCurrentExecution+exType)}')`,'sm ghost')}</div><p class="muted small">范围：${exE.wi} 当前执行分支。局限：${['提交本身不证明行为正确。','跳过用例未覆盖生产数据与外部服务。','日志仅反映本次执行，不证明外部副作用已回滚。'][exI]}</p><span class="badge b-info">已隐藏 ${exI===2?'2':'0'} 处敏感信息</span><span class="muted xs"> · ${exE.state==='SUCCEEDED'&&exCurrentExecution!=='EX-9080'?'已附于声明':exCurrentExecution==='EX-9080'?'验证报告，非工作完成声明':'草稿采集'}</span></div>`).join('');}
