  if(index===1)return `<div class="grid g12"><div class="c8">${card('manifest · 结构化清单',`<details open><summary>交付、工作项与证据</summary><pre class="code mono" style="max-height:420px;overflow:auto;white-space:pre-wrap">${exEscape(JSON.stringify(exManifest(),null,2))}</pre></details>${exTable(['文件','SHA-256','方式'],[['manifest.json',exHash(exCurrentDelivery+'manifest'),'结构化清单'],['RELEASE_NOTES.md',exHash(exCurrentDelivery+'notes'),'人工发布说明'],['evidence/report.json',exHash(exCurrentDelivery+'report'),'文件'],['evidence/execution.log',exHash(exCurrentDelivery+'log'),'脱敏全文，最大 5 MiB']])}`,{icon:'file-json'})}</div><div class="c4">${card('脱敏规则结果',exKV([['R1 · 日志','从不放入原始日志；全文已过滤'],['R2 · 秘密','替换 2 处 token / URL 凭证'],['R3 · 拒绝文件','剔除 .env 1 个；保留剔除原因'],['R4 · 白名单','图片 / PDF / 文本；未知二进制拒绝'],['R5 · 内部身份','姓名、机器名、本地路径替换为团队标签'],['R6 · 永不入包','系统提示、频道原文、知识、记忆、成本、内部理由'],['R7 · 扫描失败','整包失败，不产生部分包']])+`<div class="note ok">本 Mock 包扫描通过 · 确定性构建 · 规则版本 r1。</div>`,{icon:'shield-check'})}</div></div>`;
  if(index===2)return card('发布说明 · 只读',exKV([['起草人',who('iris')],['最后编辑人',who('morgan')+' · 人工定稿'],['编辑时间','2026-10-08 08:40'],['人工要求','无可用起草 Agent 或 30 分钟无草稿时显示「需人工撰写」；至少 50 字且最后编辑者必须是人类。']])+`<div class="bubble" style="max-width:none">${exReleaseNotes()}</div><p class="muted small">当前冻结版本已由人类定稿；更改说明会使构建指纹过期，需撤回为草稿后重建。</p>`,{icon:'file-pen'});
