  return card('时间线',`<div class="stack">${[['2026-10-05 10:00','交付包创建 · 编排者 Iris'],['2026-10-05 10:12','证据包生成 · 指纹冻结 · 脱敏规则 r1'],['2026-10-08 08:45','Morgan 作出 DELIVER 裁决 · ROLE:delivery_lead · 理由：验收证据充分 · 已重新认证'],[exD.sent||'待发送',`${exD.channel} · ${exD.contact} · 发送尝试 #1 · ${exD.sent?'成功':'排队中'}`],...(['ACCEPTED','PARTIALLY_ACCEPTED'].includes(exD.state)?[['2026-10-10 16:10','Lee · 门户回执 · 签署姓名 Lee · 回执指纹 '+exHash(exCurrentDelivery+'receipt').slice(0,8)]]:[])].map(exR=>`<div class="row wrap"><span class="mono muted small">${exR[0]}</span><span>${exR[1]}</span></div>`).join('')}${exReminderTimeline(exD)}${exD.state==='PARTIALLY_ACCEPTED'?'<a href="#/intake/IN-2039">返工来件已生成 · IN-2039</a>':''}</div>`,{icon:'history'});
