function exReminderTimeline(exD){return `<div class="stack small">${[3,7,12,14].map(exDay=>`<div class="row"><span class="badge ${exDay===14?'b-danger':'b-info'}">第 ${exDay} 天</span><span>${exDay===14?'升级给交付负责人 · 添加验收逾期风险':'提醒未回执、可签收的联系人'}</span><span class="muted xs">${['ACCEPTED','PARTIALLY_ACCEPTED'].includes(exD.state)?'已收到回执，剩余任务跳过':exD.state==='SENT'&&exDay===3?'已发送':'待发送后排期'}</span></div>`).join('')}<span class="muted xs">同一联系人 24 小时内最多一次提醒。</span></div>`;}
