function exOfflineAcceptance(){const exD=exDeliveries[exCurrentDelivery];exModal('登记线下验收',`<div class="note warn">甲方是验收主体；你以 Morgan 身份代为登记。需重新认证（acceptance_record），必须附签字件或邮件截图。原型仅演示。</div><label for="exSigner">签署人姓名</label><input id="exSigner" maxlength="200" required><label for="exProof">线下凭证</label><input id="exProof" type="file" accept=".pdf,.png,.jpg,.jpeg"><div class="stack">${exD.items.map((exId,exI)=>`<div><b>${exId}</b><label for="exReceiptResult${exI}">逐项结果</label><select id="exReceiptResult${exI}"><option value="ACCEPTED">接受</option><option value="REJECTED">拒收</option></select><label for="exReceiptCategory${exI}">拒收类别</label><select id="exReceiptCategory${exI}"><option value="">请选择</option><option value="FUNCTIONAL_DEFECT">功能缺陷</option><option value="REQUIREMENT_MISMATCH">需求不符</option><option value="STYLE">样式</option><option value="PERFORMANCE">性能</option><option value="SECURITY">安全</option><option value="OTHER">其他</option></select><label for="exReceiptComment${exI}">意见（拒收至少 10 字）</label><textarea id="exReceiptComment${exI}" maxlength="2000"></textarea></div>`).join('')}</div><label class="row"><input id="exReceiptConfirmed" type="checkbox">我确认以上为甲方对当前清单的验收结果</label>`,'exRecordAcceptance()','确认并演示重新认证',true);}
function exRecordAcceptance(){const exD=exDeliveries[exCurrentDelivery],exSigner=document.getElementById('exSigner').value.trim();if(!exSigner||!document.getElementById('exProof').files.length||!document.getElementById('exReceiptConfirmed').checked)return toast('请填写签署人、附上线下凭证并确认验收结果');const exItems=exD.items.map((exId,exI)=>({work_item_id:exId,result:document.getElementById('exReceiptResult'+exI).value,feedback_category:document.getElementById('exReceiptCategory'+exI).value,comment:document.getElementById('exReceiptComment'+exI).value.trim()}));if(exItems.some(exX=>exX.result==='REJECTED'&&(!exX.feedback_category||exX.comment.length<10)))return toast('每个拒收项都需反馈类别与至少 10 字意见');exD.receipt={signer:exSigner,items:exItems};closeModal();toast('已保留逐项线下验收演示；未调用身份验证或写入真实回执');}

