TITLES['intake']='来件详情';NAVPARENT['intake']='intakes';
function exIntakeActions(exR){if(exR.state==='RECEIVED')return exButton('手写分诊卡','exManualTriage()','primary')+exButton('转换为需求','', '',true,'尚无分诊卡，请先完成分诊')+exButton('请求澄清','exClarifyIntake()')+exButton('拒绝','exIntakeDisposition("decline")','danger');if(exR.state==='CONVERTED')return `<a class="btn primary" href="#/requirement/${exR.requirement||'R-12'}">查看需求 ${exR.requirement||'R-12'}</a><a class="btn" href="#/project/${exR.project}">查看项目</a>`;if(exR.state==='DECLINED')return `<span class="note warn">已拒绝 · 原因：${exEscape(exR.decline)}</span>`;if(exR.state==='MERGED')return `<a class="btn" href="#/intake/${exR.target}">查看合并目标 ${exR.target}</a>`;return exButton(exR.rework?'重开工作项':'转换为需求','exConvertIntake()','primary',exR.state!=='TRIAGED','当前澄清轮未结束，请等待甲方答复')+exButton('请求澄清','exClarifyIntake()','',exR.state!=='TRIAGED','已有开放澄清轮，正在等待甲方')+exButton('合并','exIntakeDisposition("merge")','',exR.state!=='TRIAGED','请先结束当前澄清轮')+exButton('拒绝','exIntakeDisposition("decline")','danger',exR.state!=='TRIAGED','请先结束当前澄清轮');}
function exIntakePanel(index){const exR=exIntakes[exCurrentIntake];if(index===0)return `<div class="grid g12"><div class="c8">${card('原文 · 不可修改',`<div class="bubble" style="max-width:none;white-space:pre-wrap">${exEscape(exR.raw)}</div><div class="sep"></div>${exKV([['开口',exR.channel],['收到时间',exR.received],['消息标识',`<span class="mono">${exEscape(exR.external)}</span>`],['原文指纹',`${exHash(exR.raw).slice(0,8)} ${exButton('复制完整值',`exCopy('${exHash(exR.raw)}')`,'sm ghost')}`]])}<b>附件</b><div class="stack small"><span>${exR.files?exR.files.length?exR.files.map(exF=>exEscape(exF.name)+' · '+Math.ceil(exF.size/1024)+' KB · 本地选取').join('<br>'):'无附件':exR.rework?'税额差异截图.png · 248 KB · 已导入':'甲方模板.csv · 12 KB · 已导入'}</span>${exR.files?'':'<span class="muted xs">历史附件 archive.zip · 未导入：超出单文件 25 MB 限制</span>'}</div>`,{icon:'file-text'})}</div><div class="c4">${card('联系人',`${exR.actor?who(exR.actor):'<b>'+exEscape(exR.contact)+'</b>'}${exKV([['组织',exEscape(exR.contact)],['身份','甲方联系人 · 需求开口'],['联系邮箱',exR.actor?'lee@contoso.example':exEscape(exR.contact)],['回复开口',exR.channel],['关联项目',exR.project?`<a href="#/project/${exR.project}">${PROJECTS.find(exP=>exP.id===exR.project).name}</a>`:'无'],['附件限制','最多 10 个 · 单个 25 MB · 合计 50 MB']])}`,{icon:'contact'})}</div></div>`;
  if(index===1&&!exR.rev)return card('协调员分诊中','<div class="empty">暂无分诊卡；你可以等待协调员，或手写首版分诊卡。</div>'+exButton('手写分诊卡','exManualTriage()','primary'));if(index===1)return card('分诊卡 · 不可变修订',`<div class="row wrap"><label for="exRevision">卡片版本</label><select id="exRevision" onchange="exRevision(this.value)">${Array.from({length:exR.rev},(_,exI)=>`<option value="${exI+1}" ${exI+1===exR.rev?'selected':''}>revision ${exI+1}</option>`).join('')}</select>${who(exR.manualCard?'morgan':'iris')}<span class="muted small">${exR.manualCard?'人工分诊':'置信度 0.87'} · 今天 09:02</span></div><div id="exRevisionBody">${exTriageBody(exR.rev)}</div>`,{icon:'clipboard-check'});
  if(index===2)return card('澄清轮次 · 问题、答复与到期',`<div class="stack"><b>第 1 轮 · ${exR.state==='CLARIFYING'?'开放 · 等待甲方答复':'已结束 / 草稿建议'}</b><span class="muted small">经 ${exR.channel} 发送 · 默认 48h、96h 提醒；168h 到期。</span><div class="bubble" style="max-width:none">问题 1：${exR.questions?exEscape(exR.questions[0]):exR.project==='p2'?'分页采用游标还是页码？单页上限是多少？':'审计角色是否可导出金额字段？'}</div><span>答复：${exR.state==='CLARIFYING'?'尚未答复':exR.rework?'请按逐行舍入修正，不改变范围。':'审计同事可导出金额，但手机号需要脱敏。'}</span><div class="bubble" style="max-width:none">问题 2：${exR.questions?exEscape(exR.questions[1]||'未设置第二个问题'):'截止日期是否为硬性要求？'}</div><span>答复：${exR.state==='CLARIFYING'?'尚未答复':'请先给出评估，我们可以协商。'}</span><span class="mono muted small">到期：2026-10-17 10:00 · 168 小时</span><div class="note info">到期未答复会返回「已分诊」并标记甲方无响应，不自动关闭来件；迟到答复仍保留在线程中。</div>${exR.state==='CLARIFYING'?exButton('取消本轮','exCancelClarification()','danger'):''}</div>`,{icon:'messages-square'});
  if(index===3)return card('转换与处置记录',exR.state==='CONVERTED'?exKV([['处置方式',exR.rework?'REOPEN_WORK_ITEMS · 重开被拒工作项':'NEW_REQUIREMENT · 作为新需求'],['需求',`<a href="#/requirement/${exR.requirement||'R-12'}">${exR.requirement||'R-12'}</a>`],['项目',`<a href="#/project/${exR.project}">${PROJECTS.find(exP=>exP.id===exR.project).name}</a>`],['转换人','Morgan · ROLE:delivery_lead'],['重开工作项',exR.rework?'<a href="#/workitem/BIL-123">BIL-123 · 演示返工分支</a>':'无']]):`<div class="empty">尚未转换为需求。${exR.rework?'甲方拒收不自动改变内部工作项状态，请由有权限的主体选择重开或范围变更。':'最新分诊卡供你确认；原文保持不变。'}</div>`,{icon:'git-pull-request'});
  return card('审计 · 只追加',exTable(['时间','主体 / 来源','动作','详情'],[[exR.received,exEscape(exR.contact),'来件已接收','原文与附件锁定 · 内容指纹 '+exHash(exR.raw).slice(0,8)],['今天 09:02','Iris · Agent','分诊卡已生成','revision '+exR.rev+' · based_on_revision '+(exR.rev-1)],['今天 09:06','Morgan · ROLE:delivery_lead','查看来件','人工关注时长自动计时'],...(exR.action?[[ '刚刚','Morgan · ROLE:delivery_lead',exR.action,'仅本地原型演示；没有真实审计落库']]:[])]),{icon:'scroll-text'});
}
function exTriageBody(revision){const exR=exIntakes[exCurrentIntake];return exKV([['修订与差异',`revision ${revision} · ${revision===1?'首次草稿':'较上一版：补充审计角色脱敏要求与验收标准'}`],['摘要',exEscape(exR.title)],['建议处置',exR.rework?'REOPEN_WORK_ITEMS · 质量返工':exR.project==='p1'?'APPEND_TO_REQUIREMENT · R-12 v3 → v4 · 范围变更':'NEW_REQUIREMENT · 既有项目的新需求'],['需求草案',exR.manualCard?exEscape(exR.manualCard.title)+' · '+exEscape(exR.manualCard.description):exEscape(exR.raw)],['验收标准',exR.manualCard?exEscape(exR.manualCard.criteria):exR.rework?'按行项目舍入后汇总；税额与发票合计一致。':exR.project==='p1'?'非财务 / 审计角色导出接口返回 403；审计导出手机号显示 138****0000；导出行为写入审计日志。':'保持字段契约；提供兼容方式；文档和测试覆盖新的接口约定。'],['建议项目',exR.project?PROJECTS.find(exP=>exP.id===exR.project).name:'待评估'],['风险',exR.manualCard?exR.manualCard.risk+' · 人工评估':'中 · 角色定义与截止日期仍需澄清'],['规模与理由','约 2 个工作项 · 预计 $6–9 · 含权限、脱敏与回归测试']])+(exR.rework?`<div class="note warn">rejected_items · 来源 D-2 / AC-2039；意见不直接绕过团队授权裁决。</div>${exTable(['被拒工作项','类别','甲方原话'],[['BIL-123','FUNCTIONAL_DEFECT · 功能缺陷',exEscape(exR.raw)]])}`:'');}
function exRevision(value){document.getElementById('exRevisionBody').innerHTML=exTriageBody(Number(value));exIcons();}
function exConvertIntake(){const exR=exIntakes[exCurrentIntake];exModal('确认处置 · '+exCurrentIntake,`<label for="exConvertMode">处置方式</label><select id="exConvertMode" onchange="exConvertHint()">${exR.rework?'<option value="REOPEN_WORK_ITEMS">重开被拒工作项（REOPEN_WORK_ITEMS）</option>':''}<option value="APPEND_TO_REQUIREMENT">追加到 R-12 · 范围变更</option><option value="NEW_REQUIREMENT">既有项目的新需求</option><option value="NEW_PROJECT">新建项目</option></select><label for="exConvertProject">项目</label><select id="exConvertProject">${PROJECTS.filter(exP=>['ACTIVE','BLOCKED','ACCEPTANCE_PENDING','PLANNING','DISCOVERY','INTAKE'].includes(exP.stage)).map(exP=>`<option value="${exP.id}" ${exP.id===exR.project?'selected':''}>${exP.name}</option>`).join('')}</select>${exR.rework?'<label class="row"><input id="exReopen" type="checkbox" checked>BIL-123 · 功能缺陷 · 税额汇总差 0.01 元</label>':''}<label for="exConvertTitle">需求标题</label><input id="exConvertTitle" maxlength="200" value="${exEscape(exR.title)}"><label for="exConvertReply">给甲方的话（可空）</label><textarea id="exConvertReply" maxlength="2000"></textarea><div id="exConvertHint"></div><label class="row"><input id="exConvertConfirm" type="checkbox">我确认处置与最新分诊卡一致</label>`,'exConvertSubmit()','确认处置',true);exConvertHint();}
function exConvertHint(){const exMode=document.getElementById('exConvertMode').value;document.getElementById('exConvertHint').innerHTML=exMode==='REOPEN_WORK_ITEMS'?'<div class="note warn">需 decision_request_changes 权限。仅重开 rejected_items 内的工作项，产生子执行，保留旧证据；不自动启动执行。</div>':exMode==='APPEND_TO_REQUIREMENT'?'<div class="note danger">范围变更不可委托 · 需重新认证（intake_convert_privileged）。基于 R-12 v3，新增权限与脱敏标准 → v4；版本冲突保留表单。</div>':exMode==='NEW_PROJECT'?'<div class="note danger">新建项目不可委托 · 需重新认证。按默认混编模式创建项目并关联联系人；原型不创建真实项目。</div>':'<div class="note info">将按最新分诊卡在所选项目创建新需求；编辑预填标题会生成人工修订版。</div>';exIcons();}
function exConvertSubmit(){const exR=exIntakes[exCurrentIntake],exMode=document.getElementById('exConvertMode').value;if(!document.getElementById('exConvertTitle').value.trim()||!document.getElementById('exConvertConfirm').checked)return toast('请填写标题并确认处置');if(exMode==='REOPEN_WORK_ITEMS'&&!document.getElementById('exReopen').checked)return toast('至少选择一个被拒工作项');if(exMode==='NEW_PROJECT'){toast('新建项目与重新认证仅演示；表单已保留，未创建真实项目');return;}if(exMode==='APPEND_TO_REQUIREMENT'){toast('需重新认证；原型未接身份服务，未变更需求范围，表单已保留');return;}exR.state='CONVERTED';exR.project=document.getElementById('exConvertProject').value;exR.requirement=exR.rework?'R-12':'R-DEMO-2041';exR.action=exMode;closeModal();route();toast('处置已记录（演示）；未启动机器执行');}
function exClarifyIntake(){exModal('请求澄清',`<div class="note info">经原开口 ${exIntakes[exCurrentIntake].channel} 发送；48h、96h 提醒，168h 到期返回已分诊，不自动关闭。</div><label for="exQuestion1">问题 1（必填）</label><textarea id="exQuestion1" maxlength="2000">审计角色是否可导出金额字段？</textarea><label for="exQuestion2">问题 2（可空）</label><textarea id="exQuestion2" maxlength="2000">截止日期是否为硬性要求？</textarea>`,'exClarifySubmit()','确认发送');}
function exClarifySubmit(){if(!document.getElementById('exQuestion1').value.trim())return toast('至少填写一个问题');const exR=exIntakes[exCurrentIntake];exR.questions=[document.getElementById('exQuestion1').value,document.getElementById('exQuestion2').value].filter(exX=>exX.trim());exR.state='CLARIFYING';exR.action='请求澄清 · 本地演示';closeModal();route();toast('已进入澄清状态（演示），未发送真实消息');}
function exCancelClarification(){exModal('取消本轮澄清','<div class="note danger">未答问题将取消，来件返回已分诊；已收到的回答与线程记录保留。需重新认证（演示）。</div>','exCancelClarificationSubmit()','取消本轮',true);}
function exCancelClarificationSubmit(){exIntakes[exCurrentIntake].state='TRIAGED';exIntakes[exCurrentIntake].action='取消澄清轮';closeModal();route();toast('本轮已取消（演示）');}
function exIntakeDisposition(kind){exModal(kind==='merge'?'合并来件':'拒绝来件',`<div class="note danger">${kind==='merge'?'合并后当前来件成为只读，原文与历史记录仍保留。':'来件将结束，保留原文、理由与审计记录。'}需重新认证（演示）。</div>${kind==='merge'?`<label for="exDispositionTarget">目标来件</label><select id="exDispositionTarget">${Object.entries(exIntakes).filter(([exId,exR])=>exId!==exCurrentIntake&&!['MERGED','DECLINED'].includes(exR.state)).map(([exId,exR])=>`<option value="${exId}">${exId} · ${exEscape(exR.title)}</option>`).join('')}</select>`:'<label for="exDeclineCode">原因码</label><select id="exDeclineCode" onchange="exSpamToggle()"><option value="OUT_OF_SCOPE">超出范围</option><option value="INSUFFICIENT_INFO">信息不足</option><option value="CAPACITY">团队产能不足</option><option value="SPAM">垃圾信息</option><option value="OTHER">其他</option></select>'}<label for="exDispositionReason">内部理由（必填）</label><textarea id="exDispositionReason" maxlength="2000"></textarea><label for="exDispositionReply">给甲方的话</label><textarea id="exDispositionReply" maxlength="2000"></textarea>${kind==='decline'?'<label class="row"><input id="exDeclineNotify" type="checkbox" checked>通知甲方（垃圾信息强制关闭）</label>':''}`,`exDispositionSubmit('${kind}')`,'确认'+(kind==='merge'?'合并':'拒绝'),true);}
function exSpamToggle(){const exSpam=document.getElementById('exDeclineCode').value==='SPAM',exNotify=document.getElementById('exDeclineNotify');exNotify.disabled=exSpam;if(exSpam)exNotify.checked=false;}
function exDispositionSubmit(kind){const exReason=document.getElementById('exDispositionReason').value.trim();if(!exReason)return toast('请填写内部理由');const exR=exIntakes[exCurrentIntake];exR.state=kind==='merge'?'MERGED':'DECLINED';exR.action=kind==='merge'?'合并来件':'拒绝来件';if(kind==='merge')exR.target=document.getElementById('exDispositionTarget').value;else exR.decline=exReason;closeModal();route();toast('处置已记录（演示），未发送真实通知');}

PAGES['intake-channels']=()=>head('Northwind Studio · 需求开口','开口设置','门户、邮件与 API 是需求开口；甲方无需进入你的内部团队。',exButton('手工录入来件','newIntake()','primary'))+`<div class="row wrap" style="margin-bottom:16px"><span class="muted small">状态预览</span>${['正常','空','错误','无权限'].map(exS=>`<button class="chip ${exPreview===exS?'on':''}" onclick="exSetPreview('${exS}')">${exS}</button>`).join('')}</div><div id="exChannelPreview">${exChannelBody()}</div>`;
TITLES['intake-channels']='开口设置';NAVPARENT['intake-channels']='intakes';
function exSetPreview(state){exPreview=state;route();}
function exChannelBody(){if(exPreview==='空')return card('还没有开口','<div class="empty">尚无门户、邮件或 API 开口。配置第一个开口后，你可以收取来件。</div>'+exButton('预览配置开口',`exSetPreview('正常')`,'primary'));if(exPreview==='错误')return card('读取失败',`<div class="note danger">开口设置暂时不可用 · 110503；已有来件不会丢失。</div>${exButton('重试',`exSetPreview('正常')`)}`);if(exPreview==='无权限')return card('无法查看',`<div class="note warn">需要 intake_read 权限；编辑还需要 intake_channel_manage。请联系团队所有者。</div>${exButton('保存设置','', '',true,'缺少 intake_channel_manage 权限')}`);return `<div class="grid g12">${[['portal','门户','globe'],['email','邮件','mail'],['api','API','webhook']].map(([exKey,exTitle,exIcon])=>`<div class="c4">${card(exTitle,exChannelCard(exKey),{icon:exIcon,right:exChannels[exKey].enabled?S('ONLINE','已启用'):S('STOPPED','已停用')})}</div>`).join('')}<div class="c4">${card('IM · v2',`<div class="empty">即将推出 · 当前版本不接收 IM 来件。</div>${exButton('启用 IM','', '',true,'v2 功能，当前版本不支持')}${exButton('绑定分诊 Agent','', '',true,'开口尚未可用')}`,{icon:'messages-square'})}</div><div class="c8">${card('甲方可见设置',`<div class="stack"><label for="exBrand">门户显示名</label><input id="exBrand" value="Northwind Studio"><label for="exLogo">品牌 Logo（≤512 KB）</label><input id="exLogo" type="file" accept="image/png,image/svg+xml,image/webp"><label for="exSupport">支持邮箱</label><input id="exSupport" type="email" value="support@northwind.example"><label for="exAiDisclosure">AI 参与展示</label><select id="exAiDisclosure" onchange="exAiPreview()"><option value="BY_MODE">按团队模式展示</option><option value="COLLABORATIVE">始终展示协作声明</option><option value="HIDDEN">隐藏</option></select><div id="exAiPreview" class="note info">甲方视角：由 AI 与工程师协作完成；全自治项目显示「由 AI Agent 完成，团队负责人监督」。未转换来件按模式不显示。</div><label class="row"><input type="checkbox">显示平台署名</label><label for="exLanguage">默认语言</label><select id="exLanguage"><option>中文</option><option>English</option><option>Bahasa Melayu</option></select>${exButton('保存甲方可见设置','exSaveBrand()','primary')}</div>`,{icon:'palette'})}</div><div class="c12">${card('联系人与链接',exTable(['联系人','邮箱 / 类型','状态','未结来件 / 有效链接','操作'],[['Lee','lee@contoso.example · 门户',S('ONLINE','有效'),'2 / 1',exButton('查看链接策略','exContactLinks()','sm')],['Adatum 文档联系人','docs@adatum · 邮件',S('ONLINE','有效'),'0 / 1','门户验收入口随交付通知发送']])+`<p class="muted small">停用开口只禁止新提交，不阻止既有澄清回复与验收；链接到期与吊销会使原会话失效。</p>`,{icon:'users'})}</div></div>`;}
function exChannelCard(key){const exC=exChannels[key];return `<div class="stack">${key==='portal'?exKV([['门户入口','#/portal · file:// 本地预览'],['默认链接有效期','30 天'],['访问码','开启 · 一次性码 10 分钟有效'],['每日提交上限','每联系人 20 条']]):key==='email'?exKV([['专属地址','northwind@intake.example'],['接收方式','IMAP / Webhook（二选一接收，不是独立开口类型）'],['健康','最近收件 41 分钟前 · 无 IMAP 错误'],['未知发件人','隔离，人工确认后转入来件']]):exKV([['服务账号','Fabrikam · client-fab-01'],['回执 Webhook','https://fabrikam.example/hooks/intake'],['鉴权','服务账号签名 · 幂等键'],['每日上限','200 条']])}<label for="exAgent-${key}">分诊 Agent</label><select id="exAgent-${key}" onchange="exBindAgent('${key}',this.value)">${['iris','lead','gale'].map(exA=>`<option value="${exA}" ${exC.agent===exA?'selected':''} ${exA==='gale'?'disabled':''}>${PEOPLE[exA].n}${exA==='gale'?' · 孤儿，需先收编':''}</option>`).join('')}</select><span class="muted xs">默认项目：${PROJECTS.find(exP=>exP.id===exC.project).name} · 回执开启 · 分诊 Agent 可发送澄清</span><span class="muted xs">提醒 48h / 96h · 超时 168h</span><div class="row wrap">${exButton('编辑配置',`exEditChannel('${key}')`,'sm')}${exButton(exC.enabled?'停用':'启用',exC.enabled?`exConfirm('停用${exC.name}','停止接收新来件；已有澄清回复和验收仍可进行。','channel|${key}')`:`exEnableChannel('${key}')`,exC.enabled?'danger sm':'primary sm')}</div></div>`;}
function exBindAgent(key,actor){exChannels[key].agent=actor;toast('分诊 Agent 绑定已更新（演示）');}
function exEnableChannel(key){exChannels[key].enabled=true;route();toast('开口已启用（演示）');}
function exAiPreview(){document.getElementById('exAiPreview').textContent=({BY_MODE:'甲方视角：由 AI 与工程师协作完成；全自治项目显示「由 AI Agent 完成，团队负责人监督」。未转换来件不显示。',COLLABORATIVE:'甲方视角：由 AI 与工程师协作完成。',HIDDEN:'甲方视角：不显示 AI 参与标签。'})[document.getElementById('exAiDisclosure').value];}
function exSaveBrand(){const exLogo=document.getElementById('exLogo').files[0];if(exLogo&&exLogo.size>512*1024)return toast('Logo 不能超过 512 KB');if(!document.getElementById('exSupport').checkValidity())return toast('请填写有效支持邮箱');toast('品牌设置已确认（演示），刷新后恢复默认值');}
function exEditChannel(key){exModal('编辑 '+exChannels[key].name,`<label for="exChannelName">名称</label><input id="exChannelName" value="${exEscape(exChannels[key].name)}"><label for="exDefaultProject">默认项目</label><select id="exDefaultProject">${PROJECTS.map(exP=>`<option value="${exP.id}" ${exP.id===exChannels[key].project?'selected':''}>${exP.name}</option>`).join('')}</select><label for="exReminderHours">提醒间隔（24–168h）</label><input id="exReminderHours" type="number" min="24" max="168" value="48"><label for="exReminderCount">提醒次数（0–5）</label><input id="exReminderCount" type="number" min="0" max="5" value="2"><label for="exTimeoutHours">超时（48–720h）</label><input id="exTimeoutHours" type="number" min="48" max="720" value="168">${key==='email'?'<label for="exEmailMethod">接收方式</label><select id="exEmailMethod"><option>IMAP</option><option>Webhook</option></select><label for="exImapHost">IMAP 主机</label><input id="exImapHost" value="imap.intake.example"><label for="exSenderPolicy">发件人策略</label><select id="exSenderPolicy"><option>未知发件人隔离</option><option>仅白名单</option></select><label for="exWhitelist">白名单</label><textarea id="exWhitelist">docs@adatum</textarea>':key==='portal'?'<label for="exLinkDays">默认链接有效期（天）</label><input id="exLinkDays" type="number" min="1" value="30"><label class="row"><input type="checkbox" checked>需访问码</label>':'<label for="exApiClient">允许的客户端</label><input id="exApiClient" value="client-fab-01"><label for="exWebhookUrl">回执 Webhook</label><input id="exWebhookUrl" type="url" value="https://fabrikam.example/hooks/intake">'}<p class="muted small">你需 intake_channel_manage 权限；保存仅影响本地原型。</p>`,`exSaveChannel('${key}')`,'保存');}
function exSaveChannel(key){const exFields=['exReminderHours','exReminderCount','exTimeoutHours'];if(!document.getElementById('exChannelName').value.trim()||exFields.some(exId=>!document.getElementById(exId).checkValidity()||document.getElementById(exId).value===''))return toast('请填写名称并检查提醒与超时范围');exChannels[key].name=document.getElementById('exChannelName').value.trim();exChannels[key].project=document.getElementById('exDefaultProject').value;closeModal();route();toast('开口配置已确认（演示）；没有连接外部服务');}
function exContactLinks(){openDrawer(card('门户访问链接策略',exKV([['联系人','Lee · can_accept=true'],['有效期','2026-11-10 · 30 天'],['访问码','开启 · 错误 5 次锁定本次取码'],['签发提示','完整链接仅展示一次，关闭后无法再次查看'],['吊销后果','Lee 的会话立即失效；需红色确认与重新认证']])+'<p class="muted small">本原型不签发真实令牌或发送邮件；可从侧栏门户查看甲方视角。</p>'));}

/* 明确授权的两个无前缀入口，供主文件列表按钮调用。 */
function newDelivery(){exModal('新建交付包',`<div class="note info">仅可选本项目已接受（ACCEPTED，L3）的工作项；已被甲方验收或其他在途交付占用的项不可重复加入。</div><label for="exNewDeliveryProject">项目</label><select id="exNewDeliveryProject" onchange="exNewDeliveryItems()">${PROJECTS.map(exP=>`<option value="${exP.id}" ${!['ACTIVE','BLOCKED','ACCEPTANCE_PENDING'].includes(exP.stage)?'disabled':''}>${exP.name}${!['ACTIVE','BLOCKED','ACCEPTANCE_PENDING'].includes(exP.stage)?' · 阶段不允许交付':''}</option>`).join('')}</select><label for="exNewDeliveryTitle">交付标题</label><input id="exNewDeliveryTitle" maxlength="200" value="账单中心 · 新交付包"><div id="exNewDeliveryItems"></div>`,'exCreateDelivery()','创建草稿');exNewDeliveryItems();}
function exNewDeliveryItems(){const exProject=document.getElementById('exNewDeliveryProject').value;document.getElementById('exNewDeliveryItems').innerHTML=exTable(['选择','工作项','阶梯','可用条件'],WI.filter(exW=>exW.p===exProject).map(exW=>{const exOccupied=Object.values(exDeliveries).some(exD=>['READY','SENT'].includes(exD.state)&&exD.items.includes(exW.id));const exDisabled=exW.s!=='ACCEPTED'||exW.l<3||exW.l===4||exOccupied;return [`<input type="checkbox" name="exDeliveryItem" value="${exW.id}" aria-label="选择 ${exW.id}" ${exDisabled?'disabled':''}>`,`${exW.id} · ${exW.t}`,ladder(exW.l),exOccupied?'已被其他在途交付占用':exW.l===4?'已被甲方验收，不可重复加入':exW.s!=='ACCEPTED'||exW.l<3?'尚未通过团队裁决，需 ACCEPTED / L3':'可加入 · 默认选择声明证据'] ;}));if(!WI.some(exW=>exW.p===exProject&&exW.s==='ACCEPTED'&&exW.l===3))document.getElementById('exNewDeliveryItems').innerHTML+='<div class="note warn">当前 Mock 无可选 ACCEPTED 工作项，请先让工作项通过团队裁决。</div>';const exCanSelect=WI.some(exW=>exW.p===exProject&&exW.s==='ACCEPTED'&&exW.l===3&&!Object.values(exDeliveries).some(exD=>['READY','SENT'].includes(exD.state)&&exD.items.includes(exW.id)));const exCreateButton=Array.from(document.querySelectorAll('button')).find(exB=>exB.getAttribute('onclick')==='exCreateDelivery()');if(exCreateButton){exCreateButton.disabled=!exCanSelect;exCreateButton.title=exCanSelect?'':'先让工作项通过团队裁决，当前无可选工作项';}exIcons();}
function exCreateDelivery(){const exItems=Array.from(document.querySelectorAll('input[name="exDeliveryItem"]:checked')).map(exI=>exI.value),exTitle=document.getElementById('exNewDeliveryTitle').value.trim();if(!exItems.length||!exTitle)return toast('请填写标题并至少选择一个 ACCEPTED 工作项');const exId='D-DEMO-'+Date.now();exDeliveries[exId]={title:exTitle,project:document.getElementById('exNewDeliveryProject').value,state:'DRAFT',count:exItems.length,contact:'待选择可签收联系人',channel:'门户',sent:null,items:exItems};closeModal();toast('已创建本地草稿；构建与正式交付不在此弹窗中执行');go('delivery/'+exId);}
function newIntake(){exModal('手工录入来件',`<div class="note info">你需 intake_submit 权限。原文提交后不可修改，附件最多 10 个、单个 25 MB、合计 50 MB。</div><label for="exNewIntakeChannel">来源开口</label><select id="exNewIntakeChannel">${Object.entries(exChannels).map(([exKey,exC])=>`<option value="${exKey}" ${!exC.enabled?'disabled':''}>${exC.name}${!exC.enabled?' · 已停用':''}</option>`).join('')}</select><label for="exNewIntakeContact">联系人</label><input id="exNewIntakeContact" maxlength="200" value="Lee · Contoso"><label for="exNewIntakeTitle">标题（1–200 字）</label><input id="exNewIntakeTitle" maxlength="200" required><label for="exNewIntakeRaw">原文（必填）</label><textarea id="exNewIntakeRaw" required></textarea><label for="exNewIntakeFiles">附件</label><input id="exNewIntakeFiles" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.md,.csv,.json,.doc,.docx,.xls,.xlsx,.zip"><p class="muted xs">文件只在本地选择，原型不会上传。</p>`,'exCreateIntake()','录入来件');}
function exCreateIntake(){const exTitle=document.getElementById('exNewIntakeTitle').value.trim(),exRaw=document.getElementById('exNewIntakeRaw').value.trim(),exContact=document.getElementById('exNewIntakeContact').value.trim(),exFiles=Array.from(document.getElementById('exNewIntakeFiles').files),exKey=document.getElementById('exNewIntakeChannel').value;if(!exTitle||!exRaw||!exContact)return toast('请填写联系人、标题与原文');if(!exChannels[exKey]||!exChannels[exKey].enabled)return toast('请选择已启用的开口');if(exFiles.length>10||exFiles.some(exF=>exF.size>25*1024*1024)||exFiles.reduce((exN,exF)=>exN+exF.size,0)>50*1024*1024)return toast('附件超限：最多 10 个、单个 25 MB、合计 50 MB');if(exFiles.some(exF=>! /\.(pdf|png|jpe?g|webp|txt|md|csv|json|docx?|xlsx?|zip)$/i.test(exF.name)))return toast('附件类型不支持，不能录入可执行文件');const exId='IN-DEMO-'+Date.now();exIntakes[exId]={title:exTitle,raw:exRaw,contact:exContact,channel:({portal:'门户',email:'邮件',api:'API'})[exKey],state:'RECEIVED',project:exChannels[exKey].project,rev:0,received:'刚刚',external:'manual-'+Date.now(),files:exFiles.map(exF=>({name:exF.name,size:exF.size})),action:'人工录入 · 待协调员分诊'};closeModal();go('intake/'+exId);toast('来件已录入本地演示，等待分诊；刷新后丢失');}

function exManualTriage(){const exR=exIntakes[exCurrentIntake];exModal('手写分诊卡 · 首版',`<label for="exManualTitle">需求草案标题</label><input id="exManualTitle" maxlength="200" value="${exEscape(exR.title)}"><label for="exManualDescription">需求描述</label><textarea id="exManualDescription">${exEscape(exR.raw)}</textarea><label for="exManualCriteria">验收标准（至少 1 条，每条最多 1000 字）</label><textarea id="exManualCriteria" maxlength="1000"></textarea><label for="exManualRisk">风险等级</label><select id="exManualRisk"><option>低</option><option selected>中</option><option>高</option></select><div class="note info">生成不可变 revision 1；原文保持不变。你需 intake_triage 权限。</div>`,'exSaveManualTriage()','保存分诊卡');}
function exSaveManualTriage(){const exTitle=document.getElementById('exManualTitle').value.trim(),exDescription=document.getElementById('exManualDescription').value.trim(),exCriteria=document.getElementById('exManualCriteria').value.trim();if(!exTitle||!exDescription||!exCriteria)return toast('请填写标题、描述和至少一条验收标准');const exR=exIntakes[exCurrentIntake];exR.manualCard={title:exTitle,description:exDescription,criteria:exCriteria,risk:document.getElementById('exManualRisk').value};exR.rev=1;exR.state='TRIAGED';exR.action='Morgan 提交人工分诊卡 revision 1';closeModal();route();toast('已保存首版分诊卡（演示）');}
